mapper.select:
select
videoUser.*
from video_user videoUser

    and videoUser.id = #{id}
    and videoUser.account = #{account}
    and videoUser.password = #{password}
    and videoUser.nick_name like concat('%',#{nickName},'%')
    and videoUser.head_img = #{headImg}
    and videoUser.create_time = #{createTime}


    limit #{current},#{pageSize}

select count(*) from video_user videoUser

    and videoUser.id = #{id}
    and videoUser.account = #{account}
    and videoUser.password = #{password}
    and videoUser.nick_name like concat('%',#{nickName},'%')
    and videoUser.head_img = #{headImg}
    and videoUser.create_time = #{createTime}
